UPDATE knowledge_info
SET current_index_version = #{indexVersion}
WHERE id = #{id}

UPDATE knowledge_info
SET current_index_version = NULL
WHERE id = #{id} AND current_index_version = #{indexVersion}

mapper.select:
SELECT id, library_code AS libraryCode, user_id AS userId, name, access_scope AS accessScope,
       description, splitter_config AS splitterConfig, retrieval_config AS retrievalConfig, current_index_version AS currentIndexVersion,
       permission_revision AS permissionRevision, status, remark,
       create_time AS createTime, update_time AS updateTime
FROM knowledge_info

    del_flag = '0'

        AND user_id = #{bo.userId}


        AND name LIKE CONCAT('%', #{bo.name}, '%')


        AND library_code = #{bo.libraryCode}


        AND status = #{bo.status}


        AND id IN

            #{id}



ORDER BY name ASC, id DESC
